from datetime import datetime
import numpy as np

# Symbolic constants for magic numbers
BOOKED = 1
AVAILABLE = 0

class MovieBookingSystem:
    def __init__(self):
        self._movies = []

    @property
    def movies(self):
        return self._movies

    @movies.setter
    def movies(self, value):
        self._movies = value

    def add_movie(self, name, price, start_time, end_time, n):
        movie = {
            'name': name,
            'price': price,
            'start_time': self._parse_time(start_time),
            'end_time': self._parse_time(end_time),
            'seats': np.zeros((n, n))
        }
        self._movies.append(movie)

    def _parse_time(self, time_str):
        return datetime.strptime(time_str, '%H:%M')

    def book_ticket(self, name, seats_to_book):
        movie = self._find_movie_by_name(name)
        if movie is None:
            return "Movie not found."

        for seat in seats_to_book:
            if not self._is_seat_available(movie, seat):
                return "Booking failed."
            self._book_seat(movie, seat)

        return "Booking success."

    def _find_movie_by_name(self, name):
        for movie in self._movies:
            if movie['name'] == name:
                return movie
        return None

    def _is_seat_available(self, movie, seat):
        return movie['seats'][seat[0]][seat[1]] == AVAILABLE

    def _book_seat(self, movie, seat):
        movie['seats'][seat[0]][seat[1]] = BOOKED

    def available_movies(self, start_time_str, end_time_str):
        start_time = self._parse_time(start_time_str)
        end_time = self._parse_time(end_time_str)

        available_movies = []
        for movie in self._movies:
            if self._is_movie_in_time_range(movie, start_time, end_time):
                available_movies.append(movie['name'])

        return available_movies

    def _is_movie_in_time_range(self, movie, start_time, end_time):
        return start_time <= movie['start_time'] and movie['end_time'] <= end_time
